using System;using System.Collections.Generic;using System.IO;using UnityEngine;using SkyIsland;
public static class PanelDismantleReview {
 public static void Validate(){int n=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("AXE PANEL FAIL "+name);n++;};var island=new HexIsland();var state=new SurvivalState();check(!PanelDismantle.AxeEquipped(state),"bare hands cannot dismantle by harvest");state.axes=1;check(!PanelDismantle.AxeEquipped(state),"axe in inventory not selected");state.selectedSlot=1;check(PanelDismantle.AxeEquipped(state),"axe selected");state.axes=0;check(!PanelDismantle.AxeEquipped(state),"empty axe slot rejected");state.axes=1;
  var floor=new PanelState{x=2};state.placedPanels.Add(floor);var player=new Vector3(0,1,0);int saves=0;check(PanelDismantle.Remove(state,floor,island,player,2.7f,()=>{saves++;return false;})=="save-failed"&&state.placedPanels.Contains(floor)&&state.panels==0,"failed save restores both board and inventory");check(PanelDismantle.Remove(state,floor,island,player,2.7f,()=>throw new IOException())=="save-failed"&&state.panels==0,"throwing save also rolls back");check(PanelDismantle.Remove(state,floor,island,new Vector3(20,1,0),2.7f,()=>true)=="range"&&state.panels==0,"distant axe hit blocked");state.panels=999;check(PanelDismantle.Remove(state,floor,island,player,2.7f,()=>true)=="full"&&state.placedPanels.Count==1,"full inventory retains building");state.panels=0;check(PanelDismantle.Remove(state,floor,island,floor.Center+Vector3.up*.7f,2.7f,()=>true)=="standing","floor under player protected");
  check(PanelDismantle.Remove(state,floor,island,player,2.7f,()=>true)=="complete"&&state.panels==1&&state.placedPanels.Count==0,"one piece returns one board");check(PanelDismantle.Remove(state,floor,island,player,2.7f,()=>true)=="missing"&&state.panels==1,"same target cannot refund twice");
  var wall=new PanelState{x=2,vertical=true};var upper=new PanelState{x=2,level=1};state.placedPanels=new List<PanelState>{wall,upper};check(PanelRules.Validate(state.placedPanels,island),"supported fixture");check(PanelDismantle.Remove(state,wall,island,player,2.7f,()=>true)=="support"&&state.placedPanels.Count==2,"supporting wall cannot drop upper floor");check(PanelDismantle.Remove(state,upper,island,player,2.7f,()=>true)=="complete","top floor removable first");check(PanelDismantle.Remove(state,wall,island,player,2.7f,()=>true)=="complete"&&state.panels==3,"wall removes after dependant");var restored=JsonUtility.FromJson<SurvivalState>(JsonUtility.ToJson(state));check(restored.panels==3&&restored.placedPanels.Count==0,"refund and removed pieces persist");
  var root=new GameObject("Dismantle collider fixture");root.layer=30;root.transform.position=new Vector3(100,100,100);var marker=root.AddComponent<PanelMarker>();marker.State=floor;root.AddComponent<BoxCollider>();Physics.SyncTransforms();check(Physics.Raycast(new Ray(root.transform.position+Vector3.back*3,Vector3.forward),out var hit,5,1<<30)&&hit.collider.GetComponentInParent<PanelMarker>()==marker,"actual collider resolves aimed board");UnityEngine.Object.DestroyImmediate(root);
  PanelReview.Validate();ConstructionReview.Validate();SurvivalReview.Validate();Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/panel-dismantle-tests.txt","PASS "+n+" axe/removal/range/support/refund/save/real-collider assertions; UTC "+DateTime.UtcNow.ToString("o")+"\nLocal Unity rules and raycast. Real mouse input, main WebGL release and mobile validation pending.");Debug.Log("SKY_PANEL_DISMANTLE_PASS "+n);
 }
